export class VoiceCapture{
 constructor({onFile,onStatus,onState}){this.onFile=onFile;this.onStatus=onStatus;this.onState=onState;this.stream=null;this.recorder=null;this.token=0;this.timer=null}
 async start(){if(this.recorder||this.stream)return;const token=++this.token;this.onState(true);this.onStatus('Esperando permiso del micrófono…');try{if(!globalThis.MediaRecorder||!navigator.mediaDevices?.getUserMedia)throw Error('La grabación no está disponible. Puedes elegir un audio desde Archivos.');const stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(token!==this.token){stream.getTracks().forEach(t=>t.stop());return}this.stream=stream;const preferred=['audio/mp4','audio/webm;codecs=opus','audio/webm','audio/ogg;codecs=opus'].find(t=>MediaRecorder.isTypeSupported?.(t));const chunks=[],r=new MediaRecorder(stream,preferred?{mimeType:preferred}:{}),start=Date.now();this.recorder=r;r.ondataavailable=e=>{if(e.data?.size)chunks.push(e.data)};r.onerror=()=>{this.cancel();this.onStatus('No se pudo completar la grabación. Importa un audio desde Archivos.')};r.onstop=()=>{this.cleanup();if(token!==this.token)return;const mime=r.mimeType||chunks[0]?.type||'audio/webm',blob=new Blob(chunks,{type:mime});if(blob.size){const file=new File([blob],'Mi-voz-'+new Date().toISOString().replace(/[:.]/g,'-')+(mime.includes('mp4')?'.m4a':mime.includes('ogg')?'.ogg':'.webm'),{type:mime});this.onFile(file);this.onStatus('Voz preparada. Añade unas palabras y guarda el recuerdo.')}else this.onStatus('No se han recibido datos de audio.');this.onState(false)};r.start(1000);this.onStatus('Grabando · 0:00');this.timer=setInterval(()=>{const sec=Math.floor((Date.now()-start)/1000);this.onStatus('Grabando · '+Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0'));if(sec>=180)this.stop()},500)}catch(e){this.cleanup();this.onState(false);this.onStatus(e.message)}}
 stop(){if(this.recorder&&this.recorder.state!=='inactive')this.recorder.stop()}
 cleanup(){clearInterval(this.timer);this.timer=null;this.stream?.getTracks().forEach(t=>t.stop());this.stream=null;this.recorder=null}
 cancel(){this.token++;if(this.recorder&&this.recorder.state!=='inactive')this.recorder.stop();this.cleanup();this.onState(false)}
}
